-- Written by python -m workload.build from workload/queries.sql. Do not edit.
-- psql -d workload -f workload/postgres_queries.sql   (from the project root)
\! mkdir -p workload/postgres

\copy (SELECT cid, name, city FROM Customer WHERE country = 'Japan' AND segment <> 0) TO 'workload/postgres/w01.csv' WITH (FORMAT csv)
\copy (SELECT oid, total FROM Orders WHERE total >= 4900 OR total <= 50) TO 'workload/postgres/w02.csv' WITH (FORMAT csv)
\copy (SELECT oid FROM Orders WHERE NOT (status = 0 OR odate < 900)) TO 'workload/postgres/w03.csv' WITH (FORMAT csv)
\copy (SELECT DISTINCT country, city FROM Customer ORDER BY country, city) TO 'workload/postgres/w04.csv' WITH (FORMAT csv)
\copy (SELECT pid, pname, weight FROM Product WHERE category = 2 ORDER BY weight DESC, pid LIMIT 5) TO 'workload/postgres/w05.csv' WITH (FORMAT csv)
\copy (SELECT name FROM Customer ORDER BY cid DESC LIMIT 7) TO 'workload/postgres/w06.csv' WITH (FORMAT csv)
\copy (SELECT COUNT(*) FROM Item WHERE qty = 11) TO 'workload/postgres/w07.csv' WITH (FORMAT csv)
\copy (SELECT MIN(total), MAX(total), SUM(total), AVG(total), COUNT(*) FROM Orders WHERE status = 2) TO 'workload/postgres/w08.csv' WITH (FORMAT csv)
\copy (SELECT status, COUNT(*) AS n, MIN(odate), MAX(shipdate) FROM Orders GROUP BY status) TO 'workload/postgres/w09.csv' WITH (FORMAT csv)
\copy (SELECT country, segment, COUNT(*) AS n FROM Customer GROUP BY country, segment HAVING COUNT(*) >= 12) TO 'workload/postgres/w10.csv' WITH (FORMAT csv)
\copy (SELECT c.country, SUM(o.total) AS revenue, AVG(o.total) AS average FROM Customer c JOIN Orders o ON c.cid = o.cid WHERE o.status <> 0 GROUP BY c.country ORDER BY revenue DESC) TO 'workload/postgres/w11.csv' WITH (FORMAT csv)
\copy (SELECT c.name, o.oid, o.total FROM Customer c JOIN Orders o ON c.cid = o.cid WHERE c.city = 'Oslo' AND o.total > 4000) TO 'workload/postgres/w12.csv' WITH (FORMAT csv)
\copy (SELECT c.name, o.oid FROM Customer c, Orders o WHERE c.cid = o.cid AND o.odate > 900 AND o.shipdate > 900 AND c.city = 'Arica' AND c.country = 'Chile') TO 'workload/postgres/w13.csv' WITH (FORMAT csv)
\copy (SELECT o.oid, i.lineno, p.pname FROM Orders o JOIN Item i ON o.oid = i.oid JOIN Product p ON i.pid = p.pid WHERE o.status = 4 AND p.category = 0 AND i.qty >= 9) TO 'workload/postgres/w14.csv' WITH (FORMAT csv)
\copy (SELECT c.name, p.pname, i.qty FROM Customer c JOIN Orders o ON c.cid = o.cid JOIN Item i ON o.oid = i.oid JOIN Product p ON i.pid = p.pid WHERE c.segment = 4 AND p.brand = 3) TO 'workload/postgres/w15.csv' WITH (FORMAT csv)
\copy (SELECT s.sname, p.pname, i.price FROM Supplier s JOIN Supply y ON s.sid = y.sid JOIN Product p ON y.pid = p.pid JOIN Item i ON i.pid = p.pid JOIN Orders o ON o.oid = i.oid WHERE s.country = 'Kenya' AND y.cost > 90 AND o.status = 3) TO 'workload/postgres/w16.csv' WITH (FORMAT csv)
\copy (SELECT c.name, s.sname FROM Customer c JOIN Orders o ON c.cid = o.cid JOIN Item i ON o.oid = i.oid JOIN Product p ON i.pid = p.pid JOIN Supply y ON y.pid = p.pid JOIN Supplier s ON s.sid = y.sid WHERE c.city = 'Tokyo' AND s.country = 'Peru' AND i.qty = 1) TO 'workload/postgres/w17.csv' WITH (FORMAT csv)
\copy (SELECT a.cid, b.cid FROM Customer a JOIN Customer b ON a.city = b.city WHERE a.cid < b.cid AND a.segment = 0 AND b.segment = 0) TO 'workload/postgres/w18.csv' WITH (FORMAT csv)
\copy (SELECT p.pid, y.sid FROM Product p JOIN Supply y ON p.pid = y.pid AND y.cost > p.weight WHERE p.brand < 2) TO 'workload/postgres/w19.csv' WITH (FORMAT csv)
\copy (SELECT a.sid, b.sid FROM Supplier a JOIN Supplier b ON a.sid < b.sid WHERE a.sid > 25) TO 'workload/postgres/w20.csv' WITH (FORMAT csv)
\copy (SELECT c.name, t.orders, t.spent FROM (SELECT cid, COUNT(*) AS orders, SUM(total) AS spent FROM Orders GROUP BY cid) AS t JOIN Customer c ON t.cid = c.cid WHERE t.orders >= 12) TO 'workload/postgres/w21.csv' WITH (FORMAT csv)
\copy (SELECT country FROM Customer UNION ALL SELECT country FROM Supplier) TO 'workload/postgres/w22.csv' WITH (FORMAT csv)
\copy (SELECT country FROM Customer UNION SELECT country FROM Supplier) TO 'workload/postgres/w23.csv' WITH (FORMAT csv)
\copy (SELECT cid FROM Orders WHERE total > 4950 INTERSECT SELECT cid FROM Orders WHERE status = 4) TO 'workload/postgres/w24.csv' WITH (FORMAT csv)
\copy ((SELECT pid FROM Product WHERE category = 1 UNION SELECT pid FROM Supply WHERE cost < 3) EXCEPT SELECT pid FROM Item WHERE qty = 10) TO 'workload/postgres/w25.csv' WITH (FORMAT csv)
